import numpy as np

def step(w,lam,s=2):
    if s==2:
        m=[np.dot(w,lam**i) for i in range(5)]
        a=(m[1]*m[2]-m[3])/(m[2]-m[1]**2)
        b=-m[2]-a*m[1]
        q=lam**2+a*lam+b
    else:
        V=np.array([lam**i for i in range(s+1)]).T
        c=np.linalg.solve(V[:,:s].T@(w[:,None]*V[:,:s]),-V[:,:s].T@(w*lam**s))
        q=lam**s+V[:,:s]@c
    h=np.dot(w,q*q)
    return w*q*q/h,h,q

if __name__=='__main__':
 for lam in [np.array([-1.,-.3,.3,1]),np.array([-1.,0,1.,2]),np.array([-1.,-.2,.4,1.,2])]:
  for seed in range(3):
    rng=np.random.default_rng(seed);w=rng.dirichlet(np.ones(len(lam)))
    for k in range(100000):
      w,h,q=step(w,lam)
      if k in [999,9999,99999]: print(lam,seed,k,w,h)

